import{_ as e,c as n,o as a,ag as o}from"./chunks/framework.bCALENAD.js";const u=JSON.parse('{"title":"Why Choose FastapiAdmin?","description":"","frontmatter":{"outline":"deep","title":"Why Choose FastapiAdmin?"},"headers":[],"relativePath":"en/overview/why.md","filePath":"en/overview/why.md","lastUpdated":1769840252000}'),i={name:"en/overview/why.md"};function r(s,t,l,d,g,m){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="why-choose-fastapiadmin" tabindex="-1">Why Choose FastapiAdmin? <a class="header-anchor" href="#why-choose-fastapiadmin" aria-label="Permalink to &quot;Why Choose FastapiAdmin?&quot;">​</a></h1><h2 id="🎯core-advantages" tabindex="-1">🎯Core Advantages <a class="header-anchor" href="#🎯core-advantages" aria-label="Permalink to &quot;🎯Core Advantages&quot;">​</a></h2><h3 id="_1-advanced-technology-stack" tabindex="-1">1. Advanced Technology Stack <a class="header-anchor" href="#_1-advanced-technology-stack" aria-label="Permalink to &quot;1. Advanced Technology Stack&quot;">​</a></h3><ul><li><strong>Backend</strong>: Based on FastAPI asynchronous framework, performance is significantly better than traditional synchronous frameworks</li><li><strong>Frontend</strong>: Based on Vue3 + TypeScript + ElementPlus, providing a type-safe and efficient development experience</li><li><strong>Mobile</strong>: Based on Uni App, achieving &quot;write once, run everywhere&quot; cross-platform development</li><li><strong>Database</strong>: Supports MySQL and MongoDB, meeting different business scenario needs</li><li><strong>Cache</strong>: Integrated Redis, improving system response speed and reducing database pressure</li></ul><h3 id="_2-complete-functional-modules" tabindex="-1">2. Complete Functional Modules <a class="header-anchor" href="#_2-complete-functional-modules" aria-label="Permalink to &quot;2. Complete Functional Modules&quot;">​</a></h3><ul><li><strong>System Management</strong>: User, role, menu, department, position management</li><li><strong>Monitoring Management</strong>: Server monitoring, cache monitoring, online users, log management</li><li><strong>Public Management</strong>: Configuration management, dictionary management, task management, file management</li><li><strong>Development Tools</strong>: Code generation, form building, interface management, workflow management</li><li><strong>Mobile Application</strong>: Unified login, personal center, workbench, message push</li></ul><h3 id="_3-highly-modular-design" tabindex="-1">3. Highly Modular Design <a class="header-anchor" href="#_3-highly-modular-design" aria-label="Permalink to &quot;3. Highly Modular Design&quot;">​</a></h3><ul><li><strong>Decoupled Architecture</strong>: Frontend and backend separation, clear layer division</li><li><strong>Plug-in Support</strong>: Modular design, easy to extend and customize</li><li><strong>Standardized Development</strong>: Unified coding standards and development specifications</li><li><strong>Easy Maintenance</strong>: Clear code structure, comprehensive documentation</li></ul><h3 id="_4-excellent-performance" tabindex="-1">4. Excellent Performance <a class="header-anchor" href="#_4-excellent-performance" aria-label="Permalink to &quot;4. Excellent Performance&quot;">​</a></h3><ul><li><strong>Asynchronous Processing</strong>: FastAPI asynchronous framework handles concurrent requests efficiently</li><li><strong>Cache Optimization</strong>: Multi-level cache strategy reduces database access</li><li><strong>Database Optimization</strong>: Reasonable index design and query optimization</li><li><strong>Load Balancing</strong>: Support for horizontal scaling to handle high concurrency</li></ul><h3 id="_5-security-and-reliability" tabindex="-1">5. Security and Reliability <a class="header-anchor" href="#_5-security-and-reliability" aria-label="Permalink to &quot;5. Security and Reliability&quot;">​</a></h3><ul><li><strong>Authentication</strong>: JWT OAuth2 authentication mechanism, secure and reliable</li><li><strong>Permission Control</strong>: RBAC model implements fine-grained permission management</li><li><strong>Data Encryption</strong>: Sensitive data encryption storage</li><li><strong>Audit Logs</strong>: Complete operation logs for traceability</li><li><strong>Error Handling</strong>: Comprehensive exception handling and error reporting mechanism</li></ul><h3 id="_6-easy-deployment-and-maintenance" tabindex="-1">6. Easy Deployment and Maintenance <a class="header-anchor" href="#_6-easy-deployment-and-maintenance" aria-label="Permalink to &quot;6. Easy Deployment and Maintenance&quot;">​</a></h3><ul><li><strong>Docker Support</strong>: One-click deployment with Docker Compose</li><li><strong>Nginx Integration</strong>: Built-in reverse proxy configuration</li><li><strong>Multi-environment Support</strong>: Development, testing, production environment isolation</li><li><strong>Monitoring Alert</strong>: Server and application monitoring, timely alerting</li><li><strong>Automated Operation and Maintenance</strong>: Support for CI/CD pipeline integration</li></ul><h3 id="_7-rich-development-tools" tabindex="-1">7. Rich Development Tools <a class="header-anchor" href="#_7-rich-development-tools" aria-label="Permalink to &quot;7. Rich Development Tools&quot;">​</a></h3><ul><li><strong>Code Generator</strong>: Automatically generates CRUD code, improving development efficiency</li><li><strong>Form Builder</strong>: Visual form design, no need for manual coding</li><li><strong>API Documentation</strong>: Automatically generated by FastAPI, real-time update</li><li><strong>Workflow Designer</strong>: Visual workflow design and execution</li><li><strong>Intelligent Assistant</strong>: AI-assisted development and system operation</li></ul><h3 id="_8-multi-platform-support" tabindex="-1">8. Multi-platform Support <a class="header-anchor" href="#_8-multi-platform-support" aria-label="Permalink to &quot;8. Multi-platform Support&quot;">​</a></h3><ul><li><strong>Web End</strong>: Responsive design, supports PC and tablet devices</li><li><strong>Mobile End</strong>: Based on Uni App, supports WeChat Mini Program, H5, iOS, Android</li><li><strong>Unified Experience</strong>: Consistent user experience across different platforms</li><li><strong>Data Synchronization</strong>: Real-time data synchronization between Web and mobile ends</li></ul><h2 id="📊comparison-with-other-frameworks" tabindex="-1">📊Comparison with Other Frameworks <a class="header-anchor" href="#📊comparison-with-other-frameworks" aria-label="Permalink to &quot;📊Comparison with Other Frameworks&quot;">​</a></h2><h3 id="fastapiadmin-vs-traditional-backend-frameworks" tabindex="-1">FastapiAdmin vs Traditional Backend Frameworks <a class="header-anchor" href="#fastapiadmin-vs-traditional-backend-frameworks" aria-label="Permalink to &quot;FastapiAdmin vs Traditional Backend Frameworks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>FastapiAdmin</th><th>Django Admin</th><th>Flask Admin</th><th>Spring Boot Admin</th></tr></thead><tbody><tr><td><strong>Technology Stack</strong></td><td>FastAPI + Vue3 + TypeScript</td><td>Django + Template</td><td>Flask + Template</td><td>Spring Boot + Thymeleaf</td></tr><tr><td><strong>Performance</strong></td><td>High (asynchronous)</td><td>Medium (synchronous)</td><td>Medium (synchronous)</td><td>Medium (synchronous)</td></tr><tr><td><strong>Frontend Experience</strong></td><td>Modern, interactive</td><td>Simple, static</td><td>Simple, static</td><td>Traditional, heavy</td></tr><tr><td><strong>Mobile Support</strong></td><td>Built-in FastApp</td><td>None</td><td>None</td><td>None</td></tr><tr><td><strong>Modularity</strong></td><td>High</td><td>Medium</td><td>Low</td><td>Medium</td></tr><tr><td><strong>Customization</strong></td><td>High</td><td>Medium</td><td>High</td><td>Medium</td></tr><tr><td><strong>Learning Curve</strong></td><td>Medium</td><td>Low</td><td>Medium</td><td>High</td></tr><tr><td><strong>Community Support</strong></td><td>Growing</td><td>Large</td><td>Medium</td><td>Large</td></tr><tr><td><strong>Deployment</strong></td><td>Docker-friendly</td><td>Traditional</td><td>Traditional</td><td>Complex</td></tr></tbody></table><h3 id="fastapiadmin-vs-other-rapid-development-platforms" tabindex="-1">FastapiAdmin vs Other Rapid Development Platforms <a class="header-anchor" href="#fastapiadmin-vs-other-rapid-development-platforms" aria-label="Permalink to &quot;FastapiAdmin vs Other Rapid Development Platforms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>FastapiAdmin</th><th>Ant Design Pro</th><th>Ruoyi Fast</th><th>Jeecg Boot</th></tr></thead><tbody><tr><td><strong>Backend Language</strong></td><td>Python</td><td>JavaScript (Node.js)</td><td>Java</td><td>Java</td></tr><tr><td><strong>Frontend Framework</strong></td><td>Vue3 + TypeScript</td><td>React + TypeScript</td><td>Vue3</td><td>Vue3</td></tr><tr><td><strong>Mobile Support</strong></td><td>Built-in FastApp</td><td>None</td><td>None</td><td>None</td></tr><tr><td><strong>Database Support</strong></td><td>MySQL, MongoDB</td><td>MySQL</td><td>MySQL</td><td>MySQL</td></tr><tr><td><strong>Asynchronous Support</strong></td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td><strong>Code Quality</strong></td><td>High</td><td>High</td><td>Medium</td><td>Medium</td></tr><tr><td><strong>Documentation</strong></td><td>Comprehensive</td><td>Comprehensive</td><td>Medium</td><td>Medium</td></tr><tr><td><strong>Ecosystem</strong></td><td>Growing</td><td>Mature</td><td>Small</td><td>Medium</td></tr><tr><td><strong>License</strong></td><td>MIT</td><td>MIT</td><td>Apache 2.0</td><td>Apache 2.0</td></tr></tbody></table><h2 id="🎯suitable-scenarios" tabindex="-1">🎯Suitable Scenarios <a class="header-anchor" href="#🎯suitable-scenarios" aria-label="Permalink to &quot;🎯Suitable Scenarios&quot;">​</a></h2><h3 id="_1-enterprise-internal-management-systems" tabindex="-1">1. Enterprise Internal Management Systems <a class="header-anchor" href="#_1-enterprise-internal-management-systems" aria-label="Permalink to &quot;1. Enterprise Internal Management Systems&quot;">​</a></h3><ul><li><strong>Human Resource Management</strong>: Employee information, attendance, performance management</li><li><strong>Financial Management</strong>: Budget, expense, invoice management</li><li><strong>OA System</strong>: Approval workflow, document management, meeting management</li><li><strong>Asset Management</strong>: Fixed assets, inventory management</li></ul><h3 id="_2-business-operation-platforms" tabindex="-1">2. Business Operation Platforms <a class="header-anchor" href="#_2-business-operation-platforms" aria-label="Permalink to &quot;2. Business Operation Platforms&quot;">​</a></h3><ul><li><strong>E-commerce Backend</strong>: Order management, product management, customer management</li><li><strong>Content Management System</strong>: Article publishing, media management, column management</li><li><strong>Customer Relationship Management</strong>: Customer information, sales pipeline, service records</li><li><strong>Marketing Management</strong>: Activity management, coupon management, data analysis</li></ul><h3 id="_3-data-analysis-platforms" tabindex="-1">3. Data Analysis Platforms <a class="header-anchor" href="#_3-data-analysis-platforms" aria-label="Permalink to &quot;3. Data Analysis Platforms&quot;">​</a></h3><ul><li><strong>Business Intelligence</strong>: Data dashboard, report generation, trend analysis</li><li><strong>Operation Analysis</strong>: User behavior analysis, traffic analysis, conversion rate analysis</li><li><strong>Financial Analysis</strong>: Revenue analysis, cost analysis, profit analysis</li><li><strong>Performance Analysis</strong>: Department performance, employee performance, project performance</li></ul><h3 id="_4-api-management-platforms" tabindex="-1">4. API Management Platforms <a class="header-anchor" href="#_4-api-management-platforms" aria-label="Permalink to &quot;4. API Management Platforms&quot;">​</a></h3><ul><li><strong>Interface Management</strong>: API documentation, testing, monitoring</li><li><strong>Developer Platform</strong>: Third-party integration, SDK management, access control</li><li><strong>Service Governance</strong>: Service registration, discovery, load balancing</li><li><strong>API Gateway</strong>: Request routing, authentication, rate limiting</li></ul><h3 id="_5-multi-platform-applications" tabindex="-1">5. Multi-platform Applications <a class="header-anchor" href="#_5-multi-platform-applications" aria-label="Permalink to &quot;5. Multi-platform Applications&quot;">​</a></h3><ul><li><strong>Enterprise Applications</strong>: Need both Web and mobile access</li><li><strong>Field Services</strong>: On-site staff use mobile terminals, backend management through Web</li><li><strong>Customer Services</strong>: Customers use mobile terminals, staff manage through Web</li><li><strong>Internal Tools</strong>: Employees use both PC and mobile terminals</li></ul><h2 id="🔧technical-advantages-in-detail" tabindex="-1">🔧Technical Advantages in Detail <a class="header-anchor" href="#🔧technical-advantages-in-detail" aria-label="Permalink to &quot;🔧Technical Advantages in Detail&quot;">​</a></h2><h3 id="_1-backend-advantages" tabindex="-1">1. Backend Advantages <a class="header-anchor" href="#_1-backend-advantages" aria-label="Permalink to &quot;1. Backend Advantages&quot;">​</a></h3><ul><li><strong>FastAPI Framework</strong>: Asynchronous processing, automatic API documentation generation, type hints</li><li><strong>SQLAlchemy 2.0</strong>: Modern ORM, support for asynchronous operations</li><li><strong>Redis Cache</strong>: High performance, support for various data structures</li><li><strong>MySQL 8.0</strong>: Stable, reliable, support for complex queries</li><li><strong>JWT Authentication</strong>: Stateless, secure, easy to scale</li></ul><h3 id="_2-frontend-advantages" tabindex="-1">2. Frontend Advantages <a class="header-anchor" href="#_2-frontend-advantages" aria-label="Permalink to &quot;2. Frontend Advantages&quot;">​</a></h3><ul><li><strong>Vue3 Composition API</strong>: Better code organization, easier reuse</li><li><strong>TypeScript</strong>: Type safety, better development experience</li><li><strong>ElementPlus</strong>: Rich components, beautiful interface</li><li><strong>Pinia</strong>: Lightweight state management, better TypeScript support</li><li><strong>Axios</strong>: Powerful HTTP client, support for interceptors</li></ul><h3 id="_3-mobile-advantages" tabindex="-1">3. Mobile Advantages <a class="header-anchor" href="#_3-mobile-advantages" aria-label="Permalink to &quot;3. Mobile Advantages&quot;">​</a></h3><ul><li><strong>Uni App</strong>: Cross-platform development, support for multiple terminals</li><li><strong>Wot Design Uni</strong>: Mobile-optimized UI components</li><li><strong>Vue3 Syntax</strong>: Consistent with Web frontend, reduced learning cost</li><li><strong>Native Performance</strong>: Near-native performance through rendering optimization</li><li><strong>Easy Packaging</strong>: One-click packaging for multiple platforms</li></ul><h3 id="_4-devops-advantages" tabindex="-1">4. DevOps Advantages <a class="header-anchor" href="#_4-devops-advantages" aria-label="Permalink to &quot;4. DevOps Advantages&quot;">​</a></h3><ul><li><strong>Docker Containerization</strong>: Consistent environment, easy deployment</li><li><strong>Docker Compose</strong>: Multi-container orchestration, simplified management</li><li><strong>Nginx Reverse Proxy</strong>: High performance, support for HTTPS</li><li><strong>CI/CD Integration</strong>: Automated testing and deployment</li><li><strong>Monitoring System</strong>: Real-time monitoring, timely alerting</li></ul><h2 id="📚complete-documentation" tabindex="-1">📚Complete Documentation <a class="header-anchor" href="#📚complete-documentation" aria-label="Permalink to &quot;📚Complete Documentation&quot;">​</a></h2><ul><li><strong>Getting Started Guide</strong>: Detailed installation and configuration steps</li><li><strong>Development Documentation</strong>: Backend, frontend, mobile development guides</li><li><strong>Deployment Documentation</strong>: Docker deployment, manual deployment, cloud deployment</li><li><strong>API Documentation</strong>: Automatically generated by FastAPI, interactive testing</li><li><strong>Best Practices</strong>: Development specifications, performance optimization, security guidelines</li></ul><h2 id="🤝active-community" tabindex="-1">🤝Active Community <a class="header-anchor" href="#🤝active-community" aria-label="Permalink to &quot;🤝Active Community&quot;">​</a></h2><ul><li><strong>Open Source</strong>: Completely open source, MIT license</li><li><strong>Community Support</strong>: GitHub, Gitee, QQ group, WeChat group</li><li><strong>Continuous Updates</strong>: Regular version updates and bug fixes</li><li><strong>Feedback Channels</strong>: Multiple channels for suggestions and issues</li><li><strong>Contribution Guide</strong>: Clear contribution process and guidelines</li></ul><h2 id="🚀future-plans" tabindex="-1">🚀Future Plans <a class="header-anchor" href="#🚀future-plans" aria-label="Permalink to &quot;🚀Future Plans&quot;">​</a></h2><ul><li><strong>AI Integration</strong>: Deep integration of AI capabilities into the development process</li><li><strong>Microservices Support</strong>: Evolution towards microservices architecture</li><li><strong>Low-code Platform</strong>: Further simplification of development process</li><li><strong>More Templates</strong>: Rich industry-specific templates</li><li><strong>Internationalization</strong>: Better support for multi-language and multi-region</li></ul><h2 id="🎉conclusion" tabindex="-1">🎉Conclusion <a class="header-anchor" href="#🎉conclusion" aria-label="Permalink to &quot;🎉Conclusion&quot;">​</a></h2><p><strong>FastapiAdmin</strong> is a <strong>modern, efficient, and comprehensive rapid development platform</strong> that combines the advantages of FastAPI, Vue3, and Uni App. It provides a complete solution for enterprise-level application development, from backend API to frontend interface, and from Web end to mobile end.</p><p>Whether you are building a small internal tool or a large enterprise system, FastapiAdmin can help you <strong>reduce development costs, improve development efficiency, and ensure system quality</strong>.</p><p>Choose FastapiAdmin, choose a better development experience!</p>',53)])])}const p=e(i,[["render",r]]);export{u as __pageData,p as default};
